import { getPostListQueryOptions } from "../queries/posts/post-list-query";
import type { Post } from "../types";
import css from "./PostListPage.module.css";

interface PostCounts {
  readonly total: number;
  readonly published: number;
  readonly draft: number;
}

/** Counts a site's posts by status — the post list already carries everything this needs. */
export function summarizePostCounts(posts: readonly Post[]): PostCounts {
  const published = posts.filter((post) => post.status === "published").length;
  return { total: posts.length, published, draft: posts.length - published };
}

export function PostListPage() {
  const { siteSlug = "" } = useParams();
  const postsQuery = useQuery(getPostListQueryOptions(siteSlug));

  return (
    <section>
